tool.parameters:
{
  "type": "object",
  "properties": {
    "cities": {
      "type": "string",
      "description": "Город проведения события на русском языке, например Москва. Если город неизвестен, уточни его у пользователя."
    },
    "starts_at_min": {
      "type": "string",
      "description": "Начало периода в ISO 8601 с часовым поясом города. Для ближайших трёх дней используй текущее время из контекста задачи."
    },
    "starts_at_max": {
      "type": "string",
      "description": "Конец периода в ISO 8601 с тем же часовым поясом. Для ближайших трёх дней вычисли начало периода плюс три дня."
    }
  },
  "required": [
    "cities",
    "starts_at_min",
    "starts_at_max"
  ],
  "additionalProperties": false
}
